G = nx.Graph()
for n in d['nodes']:
    G.add_node(n['id'], **n)
for e in d['edges']:
    G.add_edge(e['source'], e['target'], **e)

G.add_edge('app_headboard', 'ipc_cloudsync', relation='manages_cloud_sync')

comm_sets = list(louvain_communities(G, seed=42, resolution=1.0))
print('Initial comms:', len(comm_sets))

changed = True
while changed:
    changed = False
    new_sets = []
    for cset in comm_sets:
        if len(cset) < 6:
            best_target = None
            max_connections = -1
            for node in cset:
                for neighbor in G.neighbors(node):
                    if neighbor not in cset:
                        for idx, other_set in enumerate(comm_sets):
                            if neighbor in other_set:
                                conns = len(set(G.neighbors(node)) & other_set)
                                if conns > max_connections:
                                    max_connections = conns
                                    best_target = idx
                                break
            if best_target is not None:
                comm_sets[best_target].update(cset)
                changed = True
            else:
                new_sets.append(cset)
        else:
            new_sets.append(cset)
    if changed:
        comm_sets = [s for s in new_sets if len(s) > 0]

print('Consolidated comms:', len(comm_sets))
for i, s in enumerate(comm_sets):
    print(f'Cluster {i}: {len(s)} nodes')
